import sys
TWO={'Cl','Br'}
def parse(smi):
    els=[];stack=[];ring={};bonds=[];i=0
    while i<len(smi):
        c=smi[i]
        if c=='(' : stack.append(len(els)-1); i+=1; continue
        if c==')' : stack.pop(); i+=1; continue
        if c in '-=#:/\\': i+=1; continue
        if c=='[':
            j=smi.index(']',i); els.append(('X',False)); i=j+1
        elif smi[i:i+2] in TWO:
            els.append((smi[i:i+2],False)); i+=2
        elif c.isalpha():
            els.append((c.upper(),c.islower())); i+=1
        elif c.isdigit() or c=='%':
            if c=='%': num=smi[i+1:i+3]; i+=3
            else: num=c; i+=1
            if num in ring: bonds.append((ring.pop(num),len(els)-1))
            else: ring[num]=len(els)-1
        else: i+=1
    for k,p in enumerate(stack): bonds.append((p,k)) if False else None
    # backbone bonds: rebuild via second pass
    return els,bonds,smi
def graph(smi):
    els=[];prev=None;stack=[];ring={};bonds=[];i=0
    while i<len(smi):
        c=smi[i]
        if c=='(': stack.append(prev); i+=1; continue
        if c==')': prev=stack.pop(); i+=1; continue
        if c in '-=#:/\\': i+=1; continue
        if c=='[':
            j=smi.index(']',i); els.append(('X',False)); i=j+1
        elif smi[i:i+2] in TWO: els.append((smi[i:i+2],False)); i+=2
        elif c.isalpha(): els.append((c.upper(),c.islower())); i+=1
        elif c=='%':
            num=smi[i+1:i+3]; i+=3
            if num in ring: bonds.append((ring.pop(num),len(els)-1))
            else: ring[num]=len(els)-1
            prev=len(els)-1; continue
        elif c.isdigit():
            num=c; i+=1
            if num in ring: bonds.append((ring.pop(num),len(els)-1))
            else: ring[num]=len(els)-1
            prev=len(els)-1; continue
        else: i+=1; continue
        if prev is not None: bonds.append((prev,len(els)-1))
        prev=len(els)-1
    return els,bonds
def longest_aliphatic_chain(smi):
    els,bonds=graph(smi)
    adj={i:[] for i in range(len(els))}
    for a,b in bonds: adj[a].append(b); adj[b].append(a)
    carb=[i for i,(e,ar) in enumerate(els) if e=='C' and not ar]
    cs=set(carb); best=0
    def dfs(u,seen):
        nonlocal best
        best=max(best,len(seen))
        for v in adj[u]:
            if v in cs and v not in seen: dfs(v,seen|{v})
    for s in carb: dfs(s,{s})
    return best
