ILES \u5b57\u7b26\u7ea7\u5e8f\u5217\u6a21\u578b\u65cf\uff1b\u6b21\u7ea7\u4ec5\u4e00\u4e2a\u5c0f\u89c4\u6a21\u8fc1\u79fb\u6863\uff08\u672c\u6587\u9009 GFlowNet-TB\uff09\u3002", "\u3010\u8bc4\u5ba1\u786e\u7acb\u4e3a\u7ea6\u675f\u3011A3 \u4fdd\u7559\u4f46\u6807\u6ce8\u4e3a\u5b9e\u73b0\u98ce\u9669\u6700\u9ad8\u6863\uff0c\u5e76\u7b80\u5316\u4e3a\u5355\u6b65 value \u5f15\u5bfc\u7684 logit \u504f\u7f6e\uff0c\u5176\u89e3\u91ca\u529b\u635f\u5931\u5df2\u5728 \u00a74.4 \u663e\u5f0f\u58f0\u660e\u3002", "\u3010\u8bc4\u5ba1\u786e\u7acb\u4e3a\u7ea6\u675f\u3011\u4eb2\u548c\u529b\u91c7\u7528\u4ee3\u7406\u6a21\u578b + Vina \u7c7b\u5bf9\u63a5\u53cc\u8f68\uff0c\u4e8c\u8005\u5206\u6b67\u8ba1\u5165\u5e7b\u89c9\u5ea6\u91cf\uff1b\u53ef\u53ca\u6027\u53ea\u4f5c\u5956\u52b1\u4e2d\u7684\u8f6f\u60e9\u7f5a\uff0c\u786c\u7b5b\u9009\u901a\u8fc7\u7387\u4ec5\u4f5c\u8bc4\u4f30\u6307\u6807\u3002", "\u3010\u8bc4\u5ba1\u786e\u7acb\u4e3a\u7ea6\u675f\u3011\u78b3\u94fe artifact \u4ee5\u6700\u957f\u8fde\u7eed\u8102\u80aa\u65cf\u78b3\u94fe \u22658 \u4e3a\u9884\u6ce8\u518c\u4e3b\u6307\u6807\u3001\u226510 \u4e3a\u6b21\u6307\u6807\uff0c\u5e76\u62a5\u544a\u5b8c\u6574\u957f\u5ea6\u5206\u5e03\uff08\u5206\u4f4d\u6570+\u5c3e\u90e8\uff09\u3002", "\u3010\u8bc4\u5ba1\u786e\u7acb\u4e3a\u7ea6\u675f\u3011\u53cc\u57fa\u51c6\uff08\u5355\u9776\u70b9\u6027\u8d28\u4f18\u5316 + \u5206\u5e03\u5f0f\u5339\u914d\uff09\uff1b\u771f\u5b9e\u5206\u5e03\u53c2\u7167 ChEMBL \u7c7b\u5df2\u77e5\u7c7b\u836f\u5b50\u96c6\uff0c\u6392\u9664\u7eaf\u679a\u4e3e\u5e93\uff1b\u6570\u636e\u7248\u672c\u5199\u4f5c\u53ef\u66ff\u6362\u53c2\u6570\u4e14\u987b\u79bb\u7ebf\u843d\u76d8\u3002", "\u3010\u8bc4\u5ba1\u786e\u7acb\u4e3a\u7ea6\u675f\u3011held-out \u6027\u8d28\u8fc1\u79fb\u4e0e\u72ec\u7acb oracle \u4e3a\u4e3b\u5224\u636e\uff1b\u7b49 oracle \u67e5\u8be2\u6570\u4e0e\u7b49\u7b97\u529b\u53cc\u5339\u914d\u53ca\u9884\u7b97\u66f2\u7ebf\u4e3a\u72ec\u7acb\u5c0f\u8282\uff1b\u56db\u7ef4\u6307\u6807\u4e0b 8 \u7ec4\u5b8c\u6574\u7ed3\u679c\u8868\uff1b\u6587\u732e\u8868\u8ff0\u4e2d\u6027\u5316\u3002", "\u3010\u6211\u7684\u5047\u8bbe\uff0c\u53ef\u63a8\u7ffb\u3011\u4e3b\u5b9e\u9a8c\u6bcf\u7ec4 5 \u4e2a\u968f\u673a\u79cd\u5b50\uff08\u504f\u79bb\u8bc4\u5ba1'\u6cbf\u7528 3 seeds'\u7684\u5efa\u8bae\uff09\uff1a\u56e0 n=3 \u65f6 Mann-Whitney \u53cc\u4fa7\u6700\u5c0f p=0.10\uff0c\u5728 Holm \u6821\u6b63\u4e0b\u6570\u5b66\u4e0a\u4e0d\u53ef\u80fd\u663e\u8457\u3002", "\u3010\u6211\u7684\u5047\u8bbe\uff0c\u53ef\u63a8\u7ffb\u3011\u4e3b\u7ed3\u679c\u4f7f\u7528 B1i\uff08\u4ec5\u9690\u5f0f\u5206\u5e03\u6b63\u5219\u3001\u65e0\u663e\u5f0f\u7ed3\u6784\u89c4\u5219\uff09\uff0c\u663e\u5f0f\u78b3\u94fe\u7f5a\u4ec5\u4f5c\u4e3a B1e \u6d88\u878d\uff0c\u4ee5\u907f\u514d\u5faa\u73af\u8bba\u8bc1\u3002", "\u3010\u6211\u7684\u5047\u8bbe\uff0c\u53ef\u63a8\u7ffb\u3011'\u771f\u5b9e\u5206\u5e03'\u4ee5 ChEMBL \u7c7b\u836f\u5b50\u96c6\u8fd1\u4f3c\u5373\u53ef\uff0c\u4e0d\u5f15\u5165\u5408\u6210\u53ef\u53ca\u6027\u679a\u4e3e\u5e93\u6216\u4e13\u5229\u6587\u732e\u5e93\u3002", "\u3010\u6211\u7684\u5047\u8bbe\uff0c\u53ef\u63a8\u7ffb\u3011\u5bf9\u63a5\u5206\u6570\u53ef\u4f5c\u4e3a\u4eb2\u548c\u529b\u4ee3\u7406\u7684\u8bc4\u4f30\u771f\u503c\u8fd1\u4f3c\uff0c\u5c3d\u7ba1\u4e8c\u8005\u5b58\u5728\u5171\u4eab\u504f\u5dee\u98ce\u9669\uff08\u5df2\u5728\u6b8b\u7559\u4e0d\u786e\u5b9a\u70b9\u4e2d\u5217\u51fa\u7f13\u89e3\u4e0e\u9650\u5ea6\uff09\u3002", "\u3010\u6211\u7684\u5047\u8bbe\uff0c\u53ef\u63a8\u7ffb\u3011\u6700\u957f\u8fde\u7eed\u8102\u80aa\u65cf\u78b3\u94fe\u662f'\u8d85\u957f\u78b3\u94fe\u5e7b\u89c9'\u7684\u5145\u5206\u523b\u753b\u6307\u6807\uff1b\u53ef\u7591\u5b50\u7ed3\u6784 SMARTS \u7387\u4ec5\u4f5c\u63a2\u7d22\u6027\u6307\u6807\u3002", "\u3010\u6211\u7684\u5047\u8bbe\uff0c\u53ef\u63a8\u7ffb\u3011\u5bf9\u63a5\u8017\u65f6\u89c4\u5212\u503c 120 s/mol/core \u53ef\u7528\uff1b\u6b63\u5f0f\u9884\u7b97\u524d\u9700\u5728\u6267\u884c\u671f\u7528\u7ea6 200 \u5206\u5b50\u6807\u5b9a\uff08\u672c\u8bbe\u8ba1\u672a\u6807\u5b9a\uff09\u3002", "\u3010\u73af\u5883\u4e8b\u5b9e\u800c\u975e\u8981\u6c42\u3011\u672c episode \u56e0\u4f9d\u8d56\u7f3a\u5931\u3001\u65e0\u7f51\u7edc\u3001\u65e0 GPU \u800c\u4e0d\u53ef\u6267\u884c\u4efb\u4f55\u5316\u5b66/ML \u8ba1\u7b97\uff0c\u6545\u53ea\u4ea4\u4ed8\u8bbe\u8ba1\u6587\u6863\u3002"], "uncertainties": ["\u4ee3\u7406\u4eb2\u548c\u529b\u4e0e\u5bf9\u63a5\u6253\u5206\u5171\u4eab\u540c\u4e00\u504f\u5dee\u65f6\uff0cHG \u4f1a\u7cfb\u7edf\u6027\u4f4e\u4f30\u5e7b\u89c9\uff1b\u5df2\u52a0\u72ec\u7acb\u4ee3\u7406\u79cd\u5b50\u3001\u5bf9\u63a5\u91cd\u590d\u566a\u58f0\u5730\u677f\u4e0e\u8131\u9776\u4ee3\u7406\u4e09\u70b9\u7f13\u89e3\uff0c\u4f46\u65e0\u6cd5\u6839\u9664\uff0c\u6700\u7ec8\u53ef\u80fd\u53ea\u80fd\u7ed9\u51fa\u5e7b\u89c9\u95f4\u9699\u7684\u4e0a\u754c\u3002", "A3 \u7684\u5355\u6b65 value lookahead \u662f\u6709\u504f\u8fd1\u4f3c\uff1a\u5176\u89c2\u6d4b\u6548\u5e94\u4e0d\u80fd\u5916\u63a8\u4e3a'\u7406\u60f3\u89e3\u7801\u671f\u53cd\u9988'\u7684\u6548\u5e94\uff1b\u82e5\u78b3\u94fe artifact \u5728 A3 \u4e0a\u5347\uff0c\u9700\u6309\u9884\u6ce8\u518c\u6761\u6b3e\u5f52\u56e0\u4e8e\u8fd1\u4f3c\u7684\u5c40\u90e8\u589e\u78b3\u8fc7\u8ba1\u3002", "\u6bcf\u7ec4 5 seeds \u7684\u529f\u6548\u4ecd\u504f\u4f4e\uff0cA\u00d7B \u4ea4\u4e92\u68c0\u9a8c\u5f88\u53ef\u80fd\u4e0d\u663e\u8457\uff1b\u9884\u6848\u662f\u4e3b\u5224\u636e\u770b\u4e3b\u6548\u5e94\u4e0e\u6548\u5e94\u91cf CI\uff0c\u4ea4\u4e92\u4ec5\u4f5c\u673a\u5236\u8ba8\u8bba\u3002", "MMD \u5bf9\u6838\u5bbd\u4e0e\u6307\u7eb9\u9009\u62e9\u654f\u611f\uff08\u6838\u5bbd\u5df2\u7528\u53c2\u8003\u96c6\u4e2d\u4f4d\u6570\u542f\u53d1\u5f0f\u56fa\u5b9a\uff09\uff0c\u82e5 ECFP6/MACCS \u6b21\u8981\u7248\u672c\u7ed3\u8bba\u4e0d\u4e00\u81f4\uff0cD3 \u9700\u6309'\u8868\u793a\u4f9d\u8d56'\u6807\u6ce8\u3002", "\u03b4 \u654f\u611f\u6027\u5206\u6790\u7684\u8bf4\u670d\u529b\u4f9d\u8d56\u81ea\u7136\u53d8\u5f02\u5e26 [\u03b4_b, \u03b4_c] \u7684\u771f\u5b9e\u5bbd\u5ea6\uff1a\u82e5\u5e26\u5f88\u5bbd\uff0cG2/G3/G4 \u5f88\u53ef\u80fd\u88ab\u5224\u4e3a'\u9608\u503c\u4f9d\u8d56\u3001\u4e0d\u53ef\u5224\u5b9a'\uff0c\u8fd9\u662f\u8bbe\u8ba1\u9884\u671f\u7ed3\u679c\u4e4b\u4e00\u800c\u975e\u7f3a\u9677\u3002", "\u5408\u6210\u53ef\u53ca\u6027'\u786c\u901a\u8fc7\u7387'\u4f9d\u8d56\u53ef\u79bb\u7ebf\u843d\u76d8\u7684\u6b63\u5411\u5408\u6210\u68c0\u7d22\u6570\u636e\uff1b\u82e5\u4e0d\u53ef\u5f97\uff0c\u5c06\u964d\u7ea7\u4e3a SA+SCScore \u53cc\u9608\u503c\u5e76\u5df2\u660e\u786e\u6807\u6ce8\u7b49\u4ef7\u6027\u635f\u5931\u3002", "\u5bf9\u63a5\u541e\u5410\u672a\u5b9e\u6d4b\uff08120 s/mol/core \u4e3a\u89c4\u5212\u5047\u8bbe\uff09\uff1b\u82e5\u5b9e\u9645\u6162\u4e8e\u5047\u8bbe\uff0c\u4e3b\u6863\u9884\u7b97\u53ef\u80fd\u4ece\u6570\u5929\u7ea7\u5347\u81f3\u4e00\u9031\u7ea7\u3002", "\u6b21\u7ea7 GFlowNet \u6863\u53ea\u68c0\u9a8c\u65b9\u5411\u4e00\u81f4\u6027\uff1b\u82e5\u65b9\u5411\u4e0d\u4e00\u81f4\uff0c\u672c\u6587\u8bbe\u8ba1\u4e0d\u652f\u6301'\u7ed3\u8bba\u6a21\u578b\u65cf\u65e0\u5173'\u7684\u5916\u63a8\uff0c\u9700\u5728\u6700\u7ec8\u7ed3\u8bba\u4e2d\u5982\u5b9e\u6807\u6ce8\u3002", "\u57fa\u51c6\u4e59\uff08\u5206\u5e03\u5f0f\u5339\u914d\uff09\u4e2d\u56e0\u5b50 A/B \u7684\u8bed\u4e49\u6620\u5c04\uff08\u9010\u70b9\u5956\u52b1 vs \u5bc6\u5ea6\u7ea7\u76ee\u6807\uff09\u662f\u6211\u7684\u6784\u9020\u9009\u62e9\uff0c\u82e5\u8bc4\u5ba1\u8ba4\u4e3a\u8be5\u6620\u5c04\u626d\u66f2\u4e86\u53cd\u9988\u5d4c\u5165\u7684\u539f\u610f\uff0c\u5219\u4e59\u57fa\u51c6\u7684 8 \u7ec4\u8868\u5e94\u6539\u4e3a\u4ec5 A \u56e0\u5b50\u4e3b\u62a5\u544a\u3002"]}", "kind": "ActionEvent"}
